/**
 * One job: an NZB downloaded into a folder.
 */
public struct JobRequest: Equatable, Hashable {
    public var nzbPath: PathBuf
    /**
     * The exact, absolute job folder; the engine creates it.
     */
    public var outputDir: PathBuf
    /**
     * Tried in order for encrypted RARs, after the NZB's own passwords.
     */
    public var passwords: [String]
    public var preflight: Preflight
    public var onUnrepairable: OnUnrepairable
    /**
     * Free bytes on the output folder's volume as the app sees them (iOS:
     * `volumeAvailableCapacityForImportantUsage`). `None` asks the file system.
     */
    public var freeSpaceHint: UInt64?
    /**
     * The job's name (the release title the app shows): renaming calls an
     * obfuscated main file after it, never after the de-duplicated folder.
     * `None` uses the NZB's title.
     */
    public var title: String?

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(nzbPath: PathBuf, 
        /**
         * The exact, absolute job folder; the engine creates it.
         */outputDir: PathBuf, 
        /**
         * Tried in order for encrypted RARs, after the NZB's own passwords.
         */passwords: [String], preflight: Preflight, onUnrepairable: OnUnrepairable, 
        /**
         * Free bytes on the output folder's volume as the app sees them (iOS:
         * `volumeAvailableCapacityForImportantUsage`). `None` asks the file system.
         */freeSpaceHint: UInt64?, 
        /**
         * The job's name (the release title the app shows): renaming calls an
         * obfuscated main file after it, never after the de-duplicated folder.
         * `None` uses the NZB's title.
         */title: String?) {
        self.nzbPath = nzbPath
        self.outputDir = outputDir
        self.passwords = passwords
        self.preflight = preflight
        self.onUnrepairable = onUnrepairable
        self.freeSpaceHint = freeSpaceHint
        self.title = title
    }

    

    
}

