/**
 * `dl_nzb::engine::JobEvent` with labelled cases (`.phase(phase:)`).
 */

public enum JobEvent: Equatable, Hashable {
    
    /**
     * The job entered a phase. Always followed by one `Progress`.
     */
    case phase(phase: JobPhase
    )
    /**
     * At most 4 Hz, plus one on every phase change and one at the end of each
     * download phase.
     */
    case progress(progress: JobProgress
    )
    /**
     * After a pre-flight scan.
     */
    case availability(info: AvailabilityInfo
    )
    /**
     * One plain-English sentence.
     */
    case warning(message: String
    )
    /**
     * Exactly once, always last.
     */
    case finished(summary: JobSummary
    )





}

#if compiler(>=6)
extension JobEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeJobEvent: FfiConverterRustBuffer {
    typealias SwiftType = JobEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> JobEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .phase(phase: try FfiConverterTypeJobPhase.read(from: &buf)
        )
        
        case 2: return .progress(progress: try FfiConverterTypeJobProgress.read(from: &buf)
        )
        
        case 3: return .availability(info: try FfiConverterTypeAvailabilityInfo.read(from: &buf)
        )
        
        case 4: return .warning(message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .finished(summary: try FfiConverterTypeJobSummary.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: JobEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .phase(phase):
            writeInt(&buf, Int32(1))
            FfiConverterTypeJobPhase.write(phase, into: &buf)
            
        
        case let .progress(progress):
            writeInt(&buf, Int32(2))
            FfiConverterTypeJobProgress.write(progress, into: &buf)
            
        
        case let .availability(info):
            writeInt(&buf, Int32(3))
            FfiConverterTypeAvailabilityInfo.write(info, into: &buf)
            
        
        case let .warning(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .finished(summary):
            writeInt(&buf, Int32(5))
            FfiConverterTypeJobSummary.write(summary, into: &buf)
            
        }
    }
}


